revision.text:
:root {
    --color-primary: #16a085;
    --color-primary--hover: #1abc9c;
    --color-primary--active: #149174;
    --color-primary__subtle: rgba(22, 160, 133, 0.15);
    --font-family-monospace: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Menlo, Monaco, Consolas, monospace;
}

[data-theme="dark"] {
    --color-surface-0: #14171d;
    --color-surface-1: #1b2028;
    --color-surface-2: #242b35;
    --color-surface-3: #2e3744;
    --color-primary: #1abc9c;
    --color-primary--hover: #48c9b0;
    --color-primary--active: #16a085;
}

.mw-highlight pre, pre, code {
    font-family: var(--font-family-monospace) !important;
    font-size: 0.9em;
    border-radius: 6px;
}

.parch-callout {
    border-left: 4px solid #16a085;
    background-color: rgba(22, 160, 133, 0.12);
    padding: 12px 16px;
    margin: 16px 0;
    border-radius: 0 8px 8px 0;
}
.parch-callout-tip { border-left-color: #2ecc71; background-color: rgba(46, 204, 113, 0.12); }
.parch-callout-warning { border-left-color: #e67e22; background-color: rgba(230, 126, 34, 0.12); }
.parch-callout-danger { border-left-color: #e74c3c; background-color: rgba(231, 76, 60, 0.12); }
.parch-callout-info { border-left-color: #3498db; background-color: rgba(52, 152, 219, 0.12); }

{{#cargo_declare:
_table=Packages
|PackageName=String
|Version=String
|Category=String
|Repo=String
|Maintainer=String
|InstallationCommand=Wikitext
|Description=Wikitext
|UpstreamURL=URL
}}
[[Category:Templates]]

{{#cargo_store:
_table=Packages
|PackageName={{{PackageName|{{PAGENAME}}}}}
|Version={{{Version|}}}
|Category={{{Category|}}}
|Repo={{{Repo|parch-repo}}}
|Maintainer={{{Maintainer|}}}
|InstallationCommand={{{InstallationCommand|}}}
|Description={{{Description|}}}
|UpstreamURL={{{UpstreamURL|}}}
}}
{| class="wikitable" style="float: right; margin-left: 1.5em; width: 300px; border-collapse: collapse; border: 1px solid #16a085;"
|+ style="background-color: #16a085; color: #ffffff; font-weight: bold; padding: 8px; font-size: 1.1em;" | {{{PackageName|{{PAGENAME}}}}}
|-
! scope="row" style="width: 35%; background-color: rgba(22, 160, 133, 0.1);" | Version
| {{{Version|N/A}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Repository
| {{{Repo|parch-repo}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Category
| {{{Category|General}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Maintainer
| {{{Maintainer|Parch Team}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Install
| {{{InstallationCommand|sudo pacman -S {{{PackageName|{{PAGENAME}}}}}}}}
{{#if:{{{UpstreamURL|}}}|
{{!}}-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" {{!}} Upstream
{{!}} [{{{UpstreamURL}}} Website]
}}
|}
{{#if:{{{Description|}}}|{{{Description}}}|}}
[[Category:Packages]]
[[Category:{{{Category|General}}}]]

{{#cargo_declare:
_table=HardwareCompatibility
|DeviceModel=String
|Vendor=String
|DeviceType=String
|GPU_Driver=String
|WiFi_Chipset=String
|KernelVersion=String
|Status=String
|Notes=Wikitext
}}
[[Category:Templates]]

{{#cargo_store:
_table=HardwareCompatibility
|DeviceModel={{{DeviceModel|{{PAGENAME}}}}}
|Vendor={{{Vendor|}}}
|DeviceType={{{DeviceType|Laptop}}}
|GPU_Driver={{{GPU_Driver|}}}
|WiFi_Chipset={{{WiFi_Chipset|}}}
|KernelVersion={{{KernelVersion|}}}
|Status={{{Status|Working}}}
|Notes={{{Notes|}}}
}}
{| class="wikitable" style="float: right; margin-left: 1.5em; width: 320px; border: 1px solid #16a085;"
|+ style="background-color: #16a085; color: #ffffff; font-weight: bold; padding: 8px;" | {{{DeviceModel|{{PAGENAME}}}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Vendor
| {{{Vendor|Unknown}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Type
| {{{DeviceType|Laptop}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Status
| {{#switch:{{{Status|Working}}}
  |Working=✔ Working
  |Tweaks Required=⚠ Tweaks Required
  |Broken=✖ Broken
  |#default={{{Status|Working}}}
}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | GPU Driver
| {{{GPU_Driver|N/A}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Wi-Fi Chipset
| {{{WiFi_Chipset|N/A}}}
|-
! scope="row" style="background-color: rgba(22, 160, 133, 0.1);" | Tested Kernel
| {{{KernelVersion|Latest}}}
|}
=== Hardware Compatibility Notes ===
{{{Notes|No special tweaks reported. Works out-of-the-box on Parch Linux.}}}

[[Category:Hardware]]
[[Category:Hardware/{{{DeviceType|Laptop}}}]]
